CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), phone VARCHAR(16) UNIQUE NOT NULL, display_name VARCHAR(40) NOT NULL, password_hash TEXT NOT NULL, accepted_terms_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), wallet_balance INTEGER NOT NULL DEFAULT 0 CHECK (wallet_balance >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE users ADD COLUMN IF NOT EXISTS role VARCHAR(16) NOT NULL DEFAULT 'member' CHECK (role IN ('member','admin'));
CREATE TABLE IF NOT EXISTS questions (id BIGSERIAL PRIMARY KEY, prompt TEXT UNIQUE NOT NULL, category VARCHAR(60) NOT NULL, options JSONB NOT NULL, answer_index SMALLINT NOT NULL CHECK (answer_index BETWEEN 0 AND 3), source_note TEXT NOT NULL DEFAULT 'JUA editorial review', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS seen_questions (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id BIGINT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, first_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (user_id, question_id));
CREATE TABLE IF NOT EXISTS game_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, stake INTEGER NOT NULL CHECK (stake >= 50), question_ids JSONB NOT NULL, submitted_answers JSONB, score SMALLINT, opponent_name VARCHAR(80) NOT NULL DEFAULT 'JUA Challenger', status VARCHAR(20) NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS wallet_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind VARCHAR(24) NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), status VARCHAR(20) NOT NULL DEFAULT 'pending', reference VARCHAR(100) UNIQUE NOT NULL, provider_checkout_id VARCHAR(160), phone VARCHAR(16), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), confirmed_at TIMESTAMPTZ);
ALTER TABLE wallet_transactions ADD COLUMN IF NOT EXISTS provider_transaction_id VARCHAR(160) UNIQUE;
CREATE INDEX IF NOT EXISTS seen_questions_user_idx ON seen_questions(user_id, question_id);
CREATE INDEX IF NOT EXISTS wallet_transactions_pending_idx ON wallet_transactions(status, created_at);
